function StarGeometry({ opacity = 1 }: { opacity?: number }) {
  return (
    <G opacity={opacity}>
      {STAR_PATHS.map((path, index) => (
        <Path
          key={`${path.fill}-${index}`}
          fill={path.fill}
          opacity={path.opacity}
          stroke={path.stroke}
          d={path.d}
        />
      ))}
    </G>
  );
}

export function DynamicLogo({ size = 100 }: DynamicLogoProps) {
  const { colorScheme } = useColorScheme();
  const isDark = colorScheme === "dark";
  const rawMaskId = useId();
  const maskId = `dynamic-logo-mask-${rawMaskId.replace(/[^a-zA-Z0-9_-]/g, "")}`;

  return (
    <View style={{ width: size, height: size, backgroundColor: "transparent" }}>
      <Svg width="100%" height="100%" viewBox="0 0 1117 1117" style={{ backgroundColor: "transparent" }}>
        <Defs>
          <Mask
            id={maskId}
            x="0"
            y="0"
            width="1117"
            height="1117"
            maskUnits="userSpaceOnUse"
          >
            <Rect x="0" y="0" width="1117" height="1117" fill="#FFFFFF" />
            {isDark ? (
              <Circle cx="690" cy="520" r="390" fill="#000000" />
            ) : null}
          </Mask>
        </Defs>

        {isDark ? <StarGeometry opacity={0.2} /> : null}

        <G mask={`url(#${maskId})`}>
          <StarGeometry />
        </G>
      </Svg>
    </View>
  );
}

export default DynamicLogo;
